#import datetime

# Fixed user profile (Tuple)
#program needs to know who is using the Expense Tracker and perhaps their account type.
user = ("Payal", "Premium User")

# Store all expenses (List)
expenses = []

# Store unique categories (Set)
categories = set()

# Budget (Dictionary)
budget = {}

def add_expense():
    date = input("Enter date (YYYY-MM-DD): ")
    category = input("Enter category (Food, Travel, etc): ")
    amount = float(input("Enter amount: "))
    note = input("Enter note: ")

    expense = {
        "date": date,
        "category": category,
        "amount": amount,
        "note": note
    }

    expenses.append(expense)
    categories.add(category)

    print("✅ Expense added!")

def view_expenses():
    if not expenses:
        print("No expenses yet.")
        return

    for e in expenses:
        print(e["date"], "|", e["category"], "|", e["amount"], "|", e["note"])



def total_expense():
    total = 0
    for e in expenses:
        total = total + (e["amount"])

    #total = sum(e["amount"] for e in expenses)

    print("💰 Total Expense:", total)



def category_wise_expense():
    result = {}

    for e in expenses:
        cat = e["category"]

        if cat not in result:
            result[cat] = 0

        result[cat] = result[cat] + e["amount"]

    for k, v in result.items():
        print(k, ":", v)

def set_budget():
    cat = input("Enter category: ")
    amt = float(input("Set budget amount: "))
    budget[cat] = amt

def check_budget():
    spent = {}

    for e in expenses:
        cat = e["category"]

        if cat not in spent:
            spent[cat] = 0

        spent[cat] = spent[cat] + e["amount"]

    for cat in budget:
        if cat in spent:
            if spent[cat] > budget[cat]:
                print("⚠️ Budget exceeded for", cat)
        else:
            print(cat, "No expenses yet")

def show_categories():
    print("📂 Categories:", categories)

# Main menu
while True:
    print("\n==== SMART EXPENSE TRACKER ====")
    print("1. Add Expense")
    print("2. View Expenses")
    print("3. Total Expense")
    print("4. Category-wise Expense")
    print("5. Set Budget")
    print("6. Check Budget")
    print("7. Show Categories")
    print("8. Exit")

    choice = input("Enter choice: ")

    if choice == "1":
        add_expense()
    elif choice == "2":
        view_expenses()
    elif choice == "3":
        total_expense()
    elif choice == "4":
        category_wise_expense()
    elif choice == "5":
        set_budget()
    elif choice == "6":
        check_budget()
    elif choice == "7":
        show_categories()
    elif choice == "8":
        print("Goodbye!")
        break
    else:
        print("Invalid choice!")
